    use crate::core::state::{CombatSetupCard, CombatSetupMonster, GameState, OrbQueue, Side};
    use crate::registry::StaticRegistry;

    fn combat_with(card: CardId, upgraded: bool, energy: i32, stars: i32) -> Engine {
        let mut registry = StaticRegistry::standard();
        register_all_cards(&mut registry.cards);
        let mut state = GameState::single_player_test_combat(
            91,
            [CombatSetupCard {
                def: card,
                upgraded,
                costs: registry.cards.get(card).unwrap().costs_for(upgraded),
            }],
            [CombatSetupMonster {
                model: None,
                max_hp: 80,
            }],
            50,
            energy,
            1,
        );
        state.combat_mut().unwrap().player.stars = stars;
        Engine::with_registry(state, registry)
    }

    #[test]
    fn generated_registry_has_all_codex_cards() {
        let registry = StaticRegistry::standard();
        assert_eq!(registry.cards.len(), 576);
        let counts =
            registry
                .cards
                .values()
                .fold(std::collections::BTreeMap::new(), |mut out, def| {
                    *out.entry(def.pool).or_insert(0usize) += 1;
                    out
                });
        assert_eq!(counts.get(&CardPoolId::Silent), Some(&88));
        assert_eq!(counts.get(&CardPoolId::Defect), Some(&88));
        assert_eq!(counts.get(&CardPoolId::Regent), Some(&88));
        assert_eq!(counts.get(&CardPoolId::Necrobinder), Some(&88));
        assert_eq!(counts.get(&CardPoolId::Colorless), Some(&64));
        assert_eq!(counts.get(&CardPoolId::Curse), Some(&18));
        assert_eq!(counts.get(&CardPoolId::Status), Some(&11));
        assert_eq!(counts.get(&CardPoolId::Token), Some(&14));
    }

